import React, { useState, useEffect } from 'react';
import { useOutletContext } from 'react-router-dom';

const Ins_P1 = () => {
  const context = useOutletContext();
  // Initialize with current context
  const [data, setData] = useState(context?.ins?.data);

  // Sync if context updates asynchronously
  useEffect(() => {
    if (context?.ins?.data) {
      setData(context.ins.data);
    }
  }, [context?.ins?.data]);

  if (!data) return <div className="summary-box">⚠️ No Active Data Stream. Perform a query in the dashboard.</div>;

  return (
    <div className="summary-box">
      <h3>Automated Claims Verification</h3>
      <div className="metric-card"><h4>{data.score}% Confirmed</h4></div>
    </div>
  );
};
export default Ins_P1;
